                        Instruction result(Mnemonic::BRAAZ, insn);
                        GeneralEncoding enc = {};
                        enc.raw = insn;
                        bool is_64bit = true;
                        result.operands.push_back(Operand(OperandType::Register, enc.braaz64branch_reg.Rn, is_64bit));
                        return result;
